let currentUser=null,team=[],authSetup=false,treeExpanded=new Set(),calendarZoom=1,calendarScroll=null,calendarBase=new Date(new Date().getFullYear(),new Date().getMonth()-24,1),calendarPan=false,calendarSpace=false;
let data,view='overview',selected=null,detailTab='records',projectFilter='active',taskFilter='open',taskMode='list',projectQuery='',taskQuery='',month=new Date(),drawerId=null,saveQueue=Promise.resolve(),blocked=false,pendingSaves=0;
