const financeTypes={income:'Gelir',expense:'Gider'};
const financeState=e=>financeFlow(data).states.find(x=>x.id===e.status)||{name:'Tanımsız',type:'pending'};
const financeStatusLabel=e=>{const st=financeState(e);return st.id==='paid'&&st.name==='Ödendi'&&e.type==='income'?'Tahsil edildi':st.name;};
