const roles={admin:'Yönetici',lead:'Proje Sorumlusu',staff:'Büro Personeli'};
const isAdmin=()=>currentUser?.role==='admin';
function access(p){if(isAdmin())return 'edit';const g=(currentUser?.grants||[]).filter(g=>g.scope==='site'&&g.targetId===p?.id||g.scope==='client'&&g.targetId===p?.clientId);return g.some(g=>g.level==='edit')?'edit':g.some(g=>g.level==='view')?'view':null;}
const editable=p=>access(p)==='edit';
const structureEditable=p=>editable(p)&&currentUser.role!=='staff';
const clientEditable=id=>isAdmin()||(currentUser.grants||[]).some(g=>g.scope==='client'&&g.targetId===id&&g.level==='edit');
const financeAccess=p=>isAdmin()||(currentUser.grants||[]).some(g=>g.finance&&(g.scope==='site'&&g.targetId===p?.id||g.scope==='client'&&g.targetId===p?.clientId));
const financeAny=()=>isAdmin()||(currentUser.grants||[]).some(g=>g.finance);
const actorName=()=>currentUser?.name||data.settings.person;
const client=p=>data.clients.find(c=>c.id===p.clientId)?.name||'Müşteri seçilmedi';
const projectDone=p=>p.sections.some(s=>s.items.length)&&p.sections.every(s=>s.items.every(o=>completed(data,o)));
const activeItems=()=>allItems(data).filter(o=>!o.project.archived);
const lookup=id=>allItems(data).find(o=>o.id===id);
