const state=o=>stateOf(data,o)||{name:'Tanımsız',color:'gray',progress:0};
const pill=o=>`<span class="state-text${overdue(data,o)?' late':completed(data,o)?' done':''}">${esc(state(o).name)}${overdue(data,o)?' · gecikti':''}</span>`;
const empty=(title,sub,action='')=>`<div class="empty"><span class="empty-icon">${icon('project')}</span><h3>${title}</h3><p>${sub}</p>${action}</div>`;
function toast(text,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'bell':'check')+`<span>${esc(text)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
async function api(url,options={}){const r=await fetch(url,options);const result=await r.json();if(!r.ok)throw new Error(result.error||'Bağlantı kurulamadı');return result;}
function persist(message,projectId=null){if(message)data.activity.unshift({id:uid(),text:message,time:new Date().toISOString(),projectId,actor:actorName()});data.activity=data.activity.slice(0,500);const snapshot=JSON.parse(JSON.stringify(data));pendingSaves++;$('#saveState').textContent='Kaydediliyor…';saveQueue=saveQueue.then(async()=>{if(blocked)throw Error('Kayıt durduruldu. Verileri dışa aktarıp sayfayı yenileyin.');snapshot.revision=data.revision;const result=await api('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot)});data.revision=result.revision;$('#saveState').textContent='Kaydedildi';}).catch(e=>{blocked=true;$('#saveState').textContent='Kaydedilemedi — yedek alın';toast(e.message,true);}).finally(()=>{pendingSaves--;});return saveQueue;}
function nav(target,id=null){if(!isAdmin()&&['team','templates','workflows'].includes(target))return;if(target==='finance'&&!financeAny())return;view=target;selected=id;detailTab='records';document.body.classList.remove('menu-open');history.replaceState(null,'',`#${target}${id?'/'+id:''}`);render();window.scrollTo({top:0,behavior:'instant'});if(target==='team')api('/api/users').then(users=>{team=users;if(view==='team')render();}).catch(e=>toast(e.message,true));}
