  const arc=s.v?`M${f(s.x)} ${f(s.y+at)}h${f(g)}A${f(g)} ${f(g)} 0 0 1 ${f(s.x)} ${f(s.y+at+g)}`:`M${f(s.x+at)} ${f(s.y)}v${f(g)}A${f(g)} ${f(g)} 0 0 0 ${f(s.x+at+g)} ${f(s.y)}`;
