 for(let i=0;i<2;i++){const t=.2+i*.4+rnd()*.1,wl=Math.min(22,bw*.1);win.push(`<rect x="${f(x0+bw*t)}" y="${f(y0+bh-2)}" width="${f(wl)}" height="4" class="pl-win"/>`);}
 const ax=[x0,...splits.filter(s=>s.v).map(s=>s.x),x0+bw].sort((a,b)=>a-b).filter((x,i,a)=>!i||x-a[i-1]>10),ay=[y0,y0+bh];
 const axes=ax.map((x,i)=>`<path d="M${f(x)} ${f(y0-14)}V${f(y0+bh+6)}" class="pl-axis"/><circle cx="${f(x)}" cy="${f(y0-20)}" r="5.5" class="pl-bubble"/><text x="${f(x)}" y="${f(y0-17.6)}" class="pl-label">${String.fromCharCode(65+i)}</text>`).join('')+ay.map((y,i)=>`<path d="M${f(x0-14)} ${f(y)}H${f(x0+bw+6)}" class="pl-axis"/><circle cx="${f(x0-20)}" cy="${f(y)}" r="5.5" class="pl-bubble"/><text x="${f(x0-20)}" y="${f(y+2.4)}" class="pl-label">${i+1}</text>`).join('');
