 return `<svg class="plan" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><pattern id="${id}h" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0V5" class="pl-hatch"/></pattern></defs>${axes}${hatch}<rect x="${x0}" y="${y0}" width="${f(bw)}" height="${f(bh)}" class="pl-outer"/>${walls}${win.join('')}${dim}</svg>`;
